var Q7 = [
{n:1, q:'Los derechos y libertades fundamentales reconocidos en la Constitución se regulan en:', o:{a:'El Título I, que comprende los artículos 10 a 55.',b:'El Título II, artículos 56 a 65.',c:'El Título I, artículos 14 a 38.',d:'El Título III, artículos 66 a 96.'}, correct:'c', why:{c:'El Título I de la CE (arts. 10 a 55) regula los derechos y deberes fundamentales. El art.10 contiene el fundamento del orden político y los arts. 14 a 38 regulan los derechos y libertades.'}},
{n:2, q:'El art.10.1 CE establece que la dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son:', o:{a:'Derechos fundamentales exigibles ante los Tribunales.',b:'Fundamento del orden político y de la paz social.',c:'Principios rectores de la política social y económica.',d:'Derechos exclusivos de los ciudadanos españoles.'}, correct:'a', why:{a:'El art.10.1 CE establece que la dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento del orden político y de la paz social.'}},
{n:3, q:'Según el art.10.2 CE, las normas relativas a los derechos fundamentales y a las libertades que la Constitución reconoce se interpretarán de conformidad con:', o:{a:'La jurisprudencia del Tribunal Constitucional.',b:'La Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España.',c:'La legislación de la Unión Europea.',d:'Los principios generales del Derecho internacional.'}, correct:'d', why:{d:'El art.10.2 CE establece que las normas relativas a los derechos fundamentales y libertades se interpretarán de conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España.'}},
{n:4, q:'El Título I de la CE se estructura en los siguientes capítulos:', o:{a:'Tres capítulos.',b:'Cuatro capítulos.',c:'Cinco capítulos.',d:'Dos capítulos.'}, correct:'c', why:{c:'El Título I de la CE (arts. 10-55) se divide en cinco capítulos: Cap. I (De los españoles y los extranjeros), Cap. II (Derechos y libertades), Cap. III (Principios rectores), Cap. IV (Garantías) y Cap. V (Suspensión de derechos).'}},
{n:5, q:'¿Cuál de los siguientes es un derecho fundamental reconocido en la Sección 1ª del Capítulo II del Título I de la CE?', o:{a:'El derecho al trabajo.',b:'El derecho a la educación.',c:'El derecho a sindicarse.',d:'El derecho a la propiedad privada.'}, correct:'b', why:{b:'El derecho a la educación (art.27 CE) está reconocido en la Sección 1ª del Capítulo II del Título I, junto con los derechos más protegidos como la vida, la intimidad, la libertad ideológica, etc.'}},
{n:6, q:'El derecho a la igualdad ante la ley está reconocido en:', o:{a:'El art.13 CE.',b:'El art.14 CE.',c:'El art.15 CE.',d:'El art.16 CE.'}, correct:'d', why:{d:'El art.14 CE establece que los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.'}},
{n:7, q:'El derecho a la vida y a la integridad física y moral está reconocido en:', o:{a:'El art.14 CE.',b:'El art.16 CE.',c:'El art.15 CE.',d:'El art.17 CE.'}, correct:'c', why:{c:'El art.15 CE reconoce el derecho de todos a la vida y a la integridad física y moral, sin que, en ningún caso, puedan ser sometidos a tortura ni a penas o tratos inhumanos o degradantes.'}},
{n:8, q:'La Constitución Española reconoce el derecho a la vida. Respecto a la pena de muerte:', o:{a:'Está absolutamente prohibida.',b:'Queda abolida, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.',c:'Está permitida para delitos especialmente graves.',d:'Solo puede imponerse con autorización del Tribunal Supremo.'}, correct:'a', why:{a:'El art.15 CE establece que queda abolida la pena de muerte, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.'}},
{n:9, q:'La libertad ideológica, religiosa y de culto está reconocida en el artículo:', o:{a:'Art.14 CE.',b:'Art.15 CE.',c:'Art.17 CE.',d:'Art.16 CE.'}, correct:'d', why:{d:'El art.16 CE garantiza la libertad ideológica, religiosa y de culto de los individuos y las comunidades sin más limitación, en sus manifestaciones, que la necesaria para el mantenimiento del orden público protegido por la ley.'}},
{n:10, q:'Según la CE, ninguna confesión tendrá carácter estatal. El Estado reconoce la aconfesionalidad. Sin embargo, dispone que los poderes públicos tendrán en cuenta las creencias religiosas de la sociedad española y mantendrán relaciones de cooperación con la:', o:{a:'Iglesia Católica exclusivamente.',b:'Iglesia Católica y las demás confesiones.',c:'Las respuestas a y b son incorrectas.',d:'Las religiones reconocidas oficialmente.'}, correct:'b', why:{b:'El art.16.3 CE establece que ninguna confesión tendrá carácter estatal y que los poderes públicos tendrán en cuenta las creencias religiosas de la sociedad española y mantendrán las consiguientes relaciones de cooperación con la Iglesia Católica y las demás confesiones.'}},
{n:11, q:'El derecho a la libertad y a la seguridad está reconocido en:', o:{a:'El art.14 CE.',b:'El art.15 CE.',c:'El art.16 CE.',d:'El art.17 CE.'}, correct:'d', why:{d:'El art.17 CE reconoce que toda persona tiene derecho a la libertad y a la seguridad, sin que nadie pueda ser privado de su libertad sino con observancia de lo establecido en el artículo y en los casos y formas previstos en la ley.'}},
{n:12, q:'El plazo máximo de detención preventiva sin pasar a disposición judicial es de:', o:{a:'24 horas.',b:'48 horas.',c:'72 horas.',d:'5 días.'}, correct:'c', why:{c:'El art.17.2 CE establece que la detención preventiva no podrá durar más del tiempo estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial.'}},
{n:13, q:'El procedimiento de habeas corpus tiene por objeto:', o:{a:'Garantizar la tutela judicial efectiva.',b:'Garantizar la inmediata puesta a disposición judicial de toda persona detenida ilegalmente.',c:'Proteger el derecho a la presunción de inocencia.',d:'Garantizar el derecho a la asistencia letrada.'}, correct:'b', why:{b:'El art.17.4 CE establece que la ley regulará un procedimiento de habeas corpus para producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente.'}},
{n:14, q:'El derecho al honor, a la intimidad personal y familiar y a la propia imagen está reconocido en:', o:{a:'El art.17 CE.',b:'El art.18 CE.',c:'El art.19 CE.',d:'El art.20 CE.'}, correct:'c', why:{c:'El art.18.1 CE garantiza el derecho al honor, a la intimidad personal y familiar y a la propia imagen.'}},
{n:15, q:'El secreto de las comunicaciones está reconocido en el artículo:', o:{a:'Art.17 CE.',b:'Art.18 CE.',c:'Art.19 CE.',d:'Art.20 CE.'}, correct:'b', why:{b:'El art.18.3 CE garantiza el secreto de las comunicaciones y, en especial, de las postales, telegráficas y telefónicas, salvo resolución judicial.'}},
{n:16, q:'El derecho a la inviolabilidad del domicilio se reconoce en el artículo:', o:{a:'Art.17 CE.',b:'Art.18 CE.',c:'Art.19 CE.',d:'Art.20 CE.'}, correct:'b', why:{b:'El art.18.2 CE establece que el domicilio es inviolable y que ninguna entrada o registro podrá hacerse en él sin consentimiento del titular o resolución judicial, salvo en caso de flagrante delito.'}},
{n:17, q:'La entrada en un domicilio sin el consentimiento del titular es posible en los siguientes casos:', o:{a:'Solo con resolución judicial.',b:'Con resolución judicial o consentimiento del titular.',c:'Con resolución judicial, consentimiento del titular o en caso de flagrante delito.',d:'Solo en caso de flagrante delito.'}, correct:'c', why:{c:'El art.18.2 CE establece que la entrada en el domicilio requiere consentimiento del titular, resolución judicial, o en caso de flagrante delito.'}},
{n:18, q:'El derecho a elegir libremente la residencia y a circular por el territorio nacional está reconocido en:', o:{a:'El art.18 CE.',b:'El art.19 CE.',c:'El art.20 CE.',d:'El art.21 CE.'}, correct:'d', why:{d:'El art.19 CE establece que los españoles tienen derecho a elegir libremente su residencia y a circular por el territorio nacional.'}},
{n:19, q:'El derecho a la libertad de expresión, de información y de producción y creación literaria, artística, científica y técnica está reconocido en:', o:{a:'El art.19 CE.',b:'El art.20 CE.',c:'El art.21 CE.',d:'El art.22 CE.'}, correct:'b', why:{b:'El art.20 CE reconoce y protege los derechos a expresar y difundir libremente los pensamientos, ideas y opiniones, a la producción y creación literaria, artística, científica y técnica, a la libertad de cátedra y a comunicar y recibir información veraz.'}},
{n:20, q:'La censura previa está:', o:{a:'Permitida en casos excepcionales.',b:'Prohibida constitucionalmente.',c:'Permitida solo durante los estados de alarma.',d:'Permitida solo para menores de edad.'}, correct:'b', why:{b:'El art.20.2 CE establece expresamente que el ejercicio de estos derechos no puede restringirse mediante ningún tipo de censura previa. La censura previa está constitucionalmente prohibida.'}},
{n:21, q:'El derecho de reunión pacífica y sin armas:', o:{a:'Está sujeto a autorización previa.',b:'No necesita autorización previa, aunque para reuniones en lugares de tránsito público se requiere comunicación previa.',c:'Requiere siempre comunicación previa.',d:'Solo puede ejercerse en lugares privados.'}, correct:'d', why:{d:'El art.21 CE establece que el derecho de reunión pacífica y sin armas no necesita autorización previa, aunque para las reuniones en lugares de tránsito público se comunicará previamente a la autoridad.'}},
{n:22, q:'El derecho de asociación está reconocido en el artículo:', o:{a:'Art.20 CE.',b:'Art.21 CE.',c:'Art.22 CE.',d:'Art.23 CE.'}, correct:'c', why:{c:'El art.22 CE reconoce el derecho de asociación. Las asociaciones que persigan fines o utilicen medios tipificados como delito son ilegales.'}},
{n:23, q:'El derecho a participar en los asuntos públicos directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal está reconocido en:', o:{a:'El art.22 CE.',b:'El art.23 CE.',c:'El art.24 CE.',d:'El art.25 CE.'}, correct:'b', why:{b:'El art.23 CE establece que los ciudadanos tienen el derecho a participar en los asuntos públicos directamente o por medio de representantes, libremente elegidos en elecciones periódicas por sufragio universal.'}},
{n:24, q:'El derecho a la tutela judicial efectiva está reconocido en:', o:{a:'El art.23 CE.',b:'El art.24 CE.',c:'El art.25 CE.',d:'El art.26 CE.'}, correct:'b', why:{b:'El art.24 CE reconoce el derecho a obtener la tutela efectiva de los jueces y tribunales en el ejercicio de los derechos e intereses legítimos, sin que, en ningún caso, pueda producirse indefensión.'}},
{n:25, q:'El principio de legalidad penal, según el cual nadie puede ser condenado por acciones u omisiones que en el momento de producirse no constituyan delito, falta o infracción administrativa, está recogido en:', o:{a:'El art.24 CE.',b:'El art.25 CE.',c:'El art.26 CE.',d:'El art.27 CE.'}, correct:'b', why:{b:'El art.25.1 CE establece que nadie puede ser condenado o sancionado por acciones u omisiones que en el momento de producirse no constituyan delito, falta o infracción administrativa según la legislación vigente en aquel momento.'}},
{n:26, q:'Según la CE, las penas privativas de libertad y las medidas de seguridad están orientadas hacia:', o:{a:'La defensa de la sociedad.',b:'La reeducación y reinserción social.',c:'La retribución proporcional al delito.',d:'La disuasión de futuros delitos.'}, correct:'d', why:{d:'El art.25.2 CE establece que las penas privativas de libertad y las medidas de seguridad estarán orientadas hacia la reeducación y reinserción social.'}},
{n:27, q:'La CE prohíbe los Tribunales de Honor en el ámbito de la:', o:{a:'Administración civil.',b:'Administración militar.',c:'Administración pública en general.',d:'Las respuestas a y b son correctas.'}, correct:'c', why:{c:'El art.26 CE establece que se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.'}},
{n:28, q:'El derecho a la educación está reconocido en:', o:{a:'El art.26 CE.',b:'El art.27 CE.',c:'El art.28 CE.',d:'El art.29 CE.'}, correct:'a', why:{a:'El art.27 CE reconoce el derecho a la educación y la libertad de enseñanza, estableciendo la obligatoriedad y gratuidad de la enseñanza básica.'}},
{n:29, q:'La enseñanza básica en España es:', o:{a:'Obligatoria y gratuita.',b:'Obligatoria pero no gratuita.',c:'Gratuita pero no obligatoria.',d:'Obligatoria solo hasta los 14 años.'}, correct:'a', why:{a:'El art.27.4 CE establece que la enseñanza básica es obligatoria y gratuita.'}},
{n:30, q:'El derecho a sindicarse libremente está reconocido en:', o:{a:'El art.27 CE.',b:'El art.28 CE.',c:'El art.29 CE.',d:'El art.30 CE.'}, correct:'c', why:{c:'El art.28.1 CE reconoce el derecho a sindicarse libremente. La ley podrá limitar o exceptuar el ejercicio de este derecho a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar.'}},
{n:31, q:'El derecho a la huelga de los trabajadores para la defensa de sus intereses está reconocido en:', o:{a:'El art.28.1 CE.',b:'El art.28.2 CE.',c:'El art.29 CE.',d:'El art.37 CE.'}, correct:'b', why:{b:'El art.28.2 CE reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses. La ley que regule el ejercicio de este derecho establecerá las garantías precisas para asegurar el mantenimiento de los servicios esenciales de la comunidad.'}},
{n:32, q:'El derecho de petición individual y colectiva, por escrito, está reconocido en:', o:{a:'El art.28 CE.',b:'El art.29 CE.',c:'El art.30 CE.',d:'El art.31 CE.'}, correct:'b', why:{b:'El art.29 CE reconoce el derecho de petición individual y colectiva, por escrito, a los poderes públicos y a la Administración, en los términos que la ley establezca.'}},
{n:33, q:'Los miembros de las Fuerzas o Institutos armados y de los Cuerpos sometidos a disciplina militar podrán ejercer el derecho de petición:', o:{a:'Solo individualmente.',b:'Individual y colectivamente.',c:'Solo colectivamente.',d:'No pueden ejercerlo.'}, correct:'d', why:{d:'El art.29.2 CE establece que los miembros de las Fuerzas o Institutos armados o de los Cuerpos sometidos a disciplina militar podrán ejercer este derecho solo individualmente y con arreglo a lo dispuesto en su legislación específica.'}},
{n:34, q:'El derecho y el deber de defender España se recoge en:', o:{a:'El art.29 CE.',b:'El art.30 CE.',c:'El art.31 CE.',d:'El art.32 CE.'}, correct:'b', why:{b:'El art.30 CE establece que los españoles tienen el derecho y el deber de defender España. La ley fijará las obligaciones militares de los españoles y regulará el servicio militar.'}},
{n:35, q:'El derecho a contraer matrimonio con plena igualdad jurídica está reconocido en:', o:{a:'El art.31 CE.',b:'El art.32 CE.',c:'El art.33 CE.',d:'El art.34 CE.'}, correct:'b', why:{b:'El art.32 CE establece que el hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica.'}},
{n:36, q:'El derecho a la propiedad privada y a la herencia está reconocido en:', o:{a:'El art.32 CE.',b:'El art.33 CE.',c:'El art.34 CE.',d:'El art.35 CE.'}, correct:'a', why:{a:'El art.33 CE reconoce el derecho a la propiedad privada y a la herencia. La función social de estos derechos delimitará su contenido, de acuerdo con las leyes. Nadie podrá ser privado de sus bienes y derechos sino por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con lo dispuesto por las leyes.'}},
{n:37, q:'¿Qué implica la expropiación forzosa?', o:{a:'La privación de bienes sin indemnización por razones de seguridad.',b:'La privación de bienes por causa justificada de utilidad pública o interés social, mediante indemnización y conforme a las leyes.',c:'La transferencia de bienes al Estado sin compensación económica.',d:'La limitación temporal del uso de un bien privado.'}, correct:'a', why:{a:'El art.33.3 CE establece que nadie podrá ser privado de sus bienes y derechos sino por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con lo dispuesto en las leyes.'}},
{n:38, q:'El derecho-deber de trabajar y el derecho a la libre elección de profesión u oficio está reconocido en:', o:{a:'El art.34 CE.',b:'El art.35 CE.',c:'El art.36 CE.',d:'El art.37 CE.'}, correct:'b', why:{b:'El art.35.1 CE establece que todos los españoles tienen el deber de trabajar y el derecho al trabajo, a la libre elección de profesión u oficio, a la promoción a través del trabajo y a una remuneración suficiente para satisfacer sus necesidades y las de su familia.'}},
{n:39, q:'El derecho de negociación colectiva entre representantes de los trabajadores y empresarios y la fuerza vinculante de los convenios colectivos está reconocido en:', o:{a:'El art.36 CE.',b:'El art.37 CE.',c:'El art.38 CE.',d:'El art.39 CE.'}, correct:'b', why:{b:'El art.37.1 CE garantiza el derecho a la negociación colectiva laboral entre los representantes de los trabajadores y empresarios, así como la fuerza vinculante de los convenios.'}},
{n:40, q:'La libertad de empresa en el marco de la economía de mercado está reconocida en:', o:{a:'El art.37 CE.',b:'El art.38 CE.',c:'El art.39 CE.',d:'El art.40 CE.'}, correct:'d', why:{d:'El art.38 CE reconoce la libertad de empresa en el marco de la economía de mercado. Los poderes públicos garantizan y protegen su ejercicio y la defensa de la productividad, de acuerdo con las exigencias de la economía general y, en su caso, de la planificación.'}},
{n:41, q:'Los principios rectores de la política social y económica se regulan en:', o:{a:'El Capítulo I del Título I.',b:'El Capítulo II del Título I.',c:'El Capítulo III del Título I.',d:'El Capítulo IV del Título I.'}, correct:'c', why:{c:'Los principios rectores de la política social y económica se regulan en el Capítulo III del Título I (arts. 39 a 52 CE).'}},
{n:42, q:'Los principios rectores del Capítulo III del Título I:', o:{a:'Son directamente exigibles ante los Tribunales.',b:'Solo pueden ser alegados ante la jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen.',c:'Tienen el mismo nivel de protección que los derechos fundamentales.',d:'Están protegidos por el recurso de amparo.'}, correct:'b', why:{b:'El art.53.3 CE establece que el reconocimiento, respeto y protección de los principios del Cap. III informará la legislación positiva, la práctica judicial y la actuación de los poderes públicos. Solo podrán ser alegados ante la jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen.'}},
{n:43, q:'La protección de la familia y de los hijos está reconocida en:', o:{a:'El art.38 CE.',b:'El art.39 CE.',c:'El art.40 CE.',d:'El art.41 CE.'}, correct:'b', why:{b:'El art.39 CE establece que los poderes públicos aseguran la protección social, económica y jurídica de la familia.'}},
{n:44, q:'El sistema público de Seguridad Social está reconocido en:', o:{a:'El art.40 CE.',b:'El art.41 CE.',c:'El art.42 CE.',d:'El art.43 CE.'}, correct:'b', why:{b:'El art.41 CE establece que los poderes públicos mantendrán un régimen público de Seguridad Social para todos los ciudadanos, que garantice la asistencia y prestaciones sociales suficientes ante situaciones de necesidad.'}},
{n:45, q:'El derecho a la protección de la salud está reconocido en:', o:{a:'El art.42 CE.',b:'El art.43 CE.',c:'El art.44 CE.',d:'El art.45 CE.'}, correct:'b', why:{b:'El art.43 CE reconoce el derecho a la protección de la salud, estableciendo que compete a los poderes públicos organizar y tutelar la salud pública a través de medidas preventivas y de las prestaciones y servicios necesarios.'}},
{n:46, q:'El derecho al medio ambiente se reconoce en:', o:{a:'El art.44 CE.',b:'El art.45 CE.',c:'El art.46 CE.',d:'El art.47 CE.'}, correct:'b', why:{b:'El art.45 CE reconoce el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo.'}},
{n:47, q:'El derecho a una vivienda digna y adecuada está reconocido en:', o:{a:'El art.45 CE.',b:'El art.46 CE.',c:'El art.47 CE.',d:'El art.48 CE.'}, correct:'c', why:{c:'El art.47 CE establece que todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada, y que los poderes públicos promoverán las condiciones necesarias y establecerán las normas pertinentes para hacer efectivo este derecho.'}},
{n:48, q:'La atención a la tercera edad está reconocida en:', o:{a:'El art.48 CE.',b:'El art.49 CE.',c:'El art.50 CE.',d:'El art.51 CE.'}, correct:'c', why:{c:'El art.50 CE establece que los poderes públicos garantizarán, mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica a los ciudadanos durante la tercera edad.'}},
{n:49, q:'El Defensor del Pueblo es el alto comisionado de las Cortes Generales para la defensa de los derechos comprendidos en el Título I. Está regulado en:', o:{a:'El art.52 CE.',b:'El art.53 CE.',c:'El art.54 CE.',d:'El art.55 CE.'}, correct:'c', why:{c:'El art.54 CE establece que una ley orgánica regulará la institución del Defensor del Pueblo, como alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en el Título I.'}},
{n:50, q:'La suspensión general de derechos solo puede producirse cuando se declare:', o:{a:'El estado de alarma.',b:'El estado de excepción o sitio.',c:'Cualquiera de los estados de crisis previstos en el art.116 CE.',d:'El estado de guerra.'}, correct:'b', why:{b:'El art.55.1 CE establece que los derechos reconocidos en los arts. 17, 18.2 y 3, 19, 20.1.a y d y 5, 21, 28.2 y 37.2 podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio.'}},
{n:51, q:'¿Cuáles son los derechos que pueden ser suspendidos individualmente para personas determinadas en relación con las investigaciones terroristas?', o:{a:'El derecho a la libertad y el secreto de comunicaciones.',b:'La inviolabilidad del domicilio, el secreto de comunicaciones y la duración máxima de la detención preventiva.',c:'Los arts. 17.2 y 18.2 y 3 CE.',d:'Todos los de la Sección Primera del Cap. II del Título I.'}, correct:'d', why:{d:'El art.55.2 CE permite la suspensión individual de los derechos reconocidos en los arts. 17.2 y 18.2 y 3 (duración máxima de la detención preventiva, inviolabilidad del domicilio y secreto de comunicaciones) para personas determinadas en relación con investigaciones sobre actuaciones de bandas armadas o elementos terroristas.'}},
{n:52, q:'El sistema de garantías de los derechos fundamentales incluye:', o:{a:'La reserva de ley, la vinculación del contenido esencial y el recurso de amparo.',b:'Solo el recurso de amparo.',c:'Solo la reserva de ley.',d:'La vinculación directa de los poderes públicos y la tutela judicial ordinaria.'}, correct:'a', why:{a:'El art.53 CE establece un sistema de garantías que incluye: vinculación a los poderes públicos, reserva de ley con respeto al contenido esencial, tutela ante la jurisdicción ordinaria mediante procedimiento preferente y sumario, y recurso de amparo ante el TC.'}},
{n:53, q:'¿Cuáles de los siguientes derechos están protegidos por el recurso de amparo constitucional?', o:{a:'Todos los del Título I.',b:'Solo los de la Sección 1ª del Cap. II del Título I y el art.14 CE.',c:'Todos los del Capítulo II del Título I.',d:'Solo los derechos fundamentales de la Sección 1ª del Cap. II.'}, correct:'b', why:{b:'El art.53.2 CE establece que cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el art.14 y en la Sección 1ª del Capítulo II ante los Tribunales ordinarios mediante un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, mediante el recurso de amparo ante el TC.'}},
{n:54, q:'El Defensor del Pueblo es nombrado por:', o:{a:'El Gobierno.',b:'Las Cortes Generales.',c:'El Rey, a propuesta del Congreso.',d:'El Tribunal Constitucional.'}, correct:'b', why:{b:'El Defensor del Pueblo es elegido por las Cortes Generales (Congreso y Senado) y nombrado por ellas mismas para un período de cinco años.'}},
{n:55, q:'El Defensor del Pueblo puede interponer:', o:{a:'Solo el recurso de amparo.',b:'Solo el recurso de inconstitucionalidad.',c:'El recurso de amparo y el recurso de inconstitucionalidad.',d:'El recurso de casación.'}, correct:'c', why:{c:'El Defensor del Pueblo está legitimado para interponer tanto el recurso de amparo ante el TC (art.162.1.b CE) como el recurso de inconstitucionalidad (art.162.1.a CE).'}},
{n:56, q:'Los extranjeros en España gozan de los derechos reconocidos en el Título I:', o:{a:'En los mismos términos que los españoles.',b:'En los términos que establezcan los tratados y la ley.',c:'Solo los derechos fundamentales de la Sección 1ª.',d:'Ningún derecho, al no ser ciudadanos españoles.'}, correct:'b', why:{b:'El art.13 CE establece que los extranjeros gozarán en España de las libertades públicas que garantiza el Título I en los términos que establezcan los tratados y la ley.'}},
{n:57, q:'El derecho de sufragio activo (votar) en elecciones municipales puede ser extendido a los extranjeros comunitarios y a los de otros países mediante:', o:{a:'Ley orgánica.',b:'Tratado internacional.',c:'Real decreto.',d:'Atendiendo al criterio de reciprocidad.'}, correct:'d', why:{d:'El art.13.2 CE establece que, atendiendo a criterios de reciprocidad, podrá reconocerse a los extranjeros el derecho de sufragio activo y pasivo en las elecciones municipales, en los términos que establezca la ley.'}},
{n:58, q:'El derecho de asilo está reconocido en:', o:{a:'El art.13.2 CE.',b:'El art.13.3 CE.',c:'El art.13.4 CE.',d:'El art.14 CE.'}, correct:'c', why:{c:'El art.13.4 CE establece que la ley establecerá los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo en España.'}},
{n:59, q:'La igualdad reconocida en el art.14 CE prohíbe la discriminación por razón de:', o:{a:'Solo sexo y raza.',b:'Nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.',c:'Solo por razones políticas o religiosas.',d:'Solo discriminaciones directas, no las indirectas.'}, correct:'d', why:{d:'El art.14 CE establece que los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.'}},
{n:60, q:'El contenido esencial de los derechos fundamentales:', o:{a:'Puede ser limitado por ley ordinaria.',b:'No puede ser afectado ni por ley orgánica.',c:'Debe ser respetado incluso cuando el legislador los regule.',d:'Solo lo determina el Tribunal Supremo.'}, correct:'c', why:{c:'El art.53.1 CE establece que los derechos y libertades reconocidos en el Capítulo II del Título I vinculan a todos los poderes públicos. Solo por ley, que en todo caso deberá respetar su contenido esencial, podrá regularse el ejercicio de tales derechos y libertades.'}},
{n:61, q:'El derecho a sindicarse de los miembros de las Fuerzas Armadas y Cuerpos sometidos a disciplina militar:', o:{a:'Es igual que el de cualquier ciudadano.',b:'Puede ser limitado por ley.',c:'Está completamente prohibido.',d:'Solo puede ejercerse a través de asociaciones profesionales.'}, correct:'b', why:{b:'El art.28.1 CE establece que la ley podrá limitar o exceptuar el ejercicio del derecho de sindicación a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar.'}},
{n:62, q:'El derecho a la educación incluye:', o:{a:'El derecho a la escolarización gratuita en todos los niveles.',b:'La libertad de enseñanza, la libertad de crear centros docentes y la autonomía universitaria.',c:'El derecho a elegir el idioma de instrucción.',d:'El derecho a la educación privada financiada con fondos públicos.'}, correct:'d', why:{d:'El art.27 CE reconoce el derecho a la educación y la libertad de enseñanza, incluyendo: la enseñanza básica obligatoria y gratuita, la libertad de creación de centros docentes y la autonomía universitaria.'}},
{n:63, q:'Los poderes públicos tienen el deber de garantizar la inspección y homologación del sistema educativo. Este deber está reconocido en:', o:{a:'El art.25 CE.',b:'El art.26 CE.',c:'El art.27 CE.',d:'El art.28 CE.'}, correct:'c', why:{c:'El art.27.8 CE establece que los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.'}},
{n:64, q:'El derecho al trabajo se reconoce en la CE como:', o:{a:'Un derecho fundamental de la Sección 1ª.',b:'Un derecho de la Sección 2ª del Capítulo II del Título I.',c:'Un principio rector de la política social y económica.',d:'Un derecho exclusivo de los trabajadores asalariados.'}, correct:'b', why:{b:'El derecho al trabajo (art.35 CE) se encuentra en la Sección 2ª del Capítulo II del Título I, siendo un derecho con menor nivel de protección que los de la Sección 1ª.'}},
{n:65, q:'El Defensor del Pueblo tiene un mandato de:', o:{a:'Cuatro años.',b:'Cinco años.',c:'Seis años.',d:'Nueve años.'}, correct:'d', why:{d:'La Ley Orgánica del Defensor del Pueblo establece que su mandato es de cinco años, pudiendo ser reelegido.'}},
{n:66, q:'El recurso de amparo constitucional protege a los ciudadanos frente a:', o:{a:'Solo los actos del Gobierno.',b:'Las violaciones de derechos fundamentales causadas por actos de los poderes públicos.',c:'Las violaciones causadas por particulares.',d:'Solo las violaciones causadas por la Administración.'}, correct:'c', why:{c:'El recurso de amparo constitucional protege frente a las violaciones de derechos y libertades de los arts. 14 a 30 CE originadas por disposiciones, actos jurídicos o vías de hecho de los poderes públicos.'}},
{n:67, q:'El principio de irretroactividad de las disposiciones sancionadoras no favorables está consagrado en:', o:{a:'El art.24 CE.',b:'El art.25.1 CE.',c:'El art.9.3 CE.',d:'El art.10 CE.'}, correct:'b', why:{b:'El principio de irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales está consagrado en el art.9.3 CE como garantía del Estado de Derecho.'}},
{n:68, q:'El secreto de las comunicaciones puede ser levantado:', o:{a:'Por la policía en caso de urgencia.',b:'Solo por resolución judicial.',c:'Por el Ministerio del Interior en casos de terrorismo.',d:'Por el Ministerio Fiscal.'}, correct:'d', why:{d:'El art.18.3 CE establece que el secreto de las comunicaciones solo puede levantarse en virtud de resolución judicial.'}},
{n:69, q:'La propiedad privada tiene una función:', o:{a:'Puramente individual.',b:'Social que delimita su contenido de acuerdo con las leyes.',c:'Solo económica.',d:'Solo patrimonial.'}, correct:'b', why:{b:'El art.33.2 CE establece que la función social de la propiedad privada delimitará su contenido de acuerdo con las leyes.'}},
{n:70, q:'¿Pueden las personas jurídicas ser titulares de derechos fundamentales?', o:{a:'No, en ningún caso.',b:'Sí, de algunos derechos fundamentales compatibles con su naturaleza.',c:'Solo si son asociaciones sin ánimo de lucro.',d:'Solo si son entidades públicas.'}, correct:'a', why:{a:'Las personas jurídicas pueden ser titulares de algunos derechos fundamentales (honor, intimidad empresarial, inviolabilidad del domicilio, tutela judicial efectiva, etc.) en la medida en que sean compatibles con su naturaleza, según la doctrina del TC.'}},
{n:71, q:'La objeción de conciencia al servicio militar está reconocida en:', o:{a:'El art.28 CE.',b:'El art.29 CE.',c:'El art.30 CE.',d:'El art.31 CE.'}, correct:'c', why:{c:'El art.30.2 CE establece que la ley fijará las obligaciones militares de los españoles y regulará, con las debidas garantías, la objeción de conciencia, así como las demás causas de exención del servicio militar obligatorio.'}},
{n:72, q:'La inviolabilidad del domicilio protege:', o:{a:'Solo a los ciudadanos españoles.',b:'A toda persona, independientemente de su nacionalidad.',c:'Solo a los propietarios del inmueble.',d:'Solo a los arrendatarios.'}, correct:'c', why:{c:'El art.18.2 CE establece que el domicilio es inviolable para toda persona, no solo para los propietarios o los ciudadanos españoles.'}},
{n:73, q:'El derecho de reunión puede limitarse cuando:', o:{a:'El Gobierno lo estime conveniente.',b:'Existan razones fundadas de alteración del orden público con peligro para personas o bienes.',c:'La Policía lo considere necesario.',d:'El número de participantes supere un límite legal.'}, correct:'b', why:{b:'El art.21.2 CE establece que la autoridad podrá prohibir la reunión cuando existan razones fundadas de alteración del orden público con peligro para personas o bienes.'}},
{n:74, q:'¿Qué órgano tiene la competencia para controlar el cumplimiento del deber de los poderes públicos de garantizar los derechos fundamentales?', o:{a:'El Gobierno.',b:'El Defensor del Pueblo.',c:'El Tribunal Constitucional y los Tribunales ordinarios.',d:'Solo el Tribunal Constitucional.'}, correct:'c', why:{c:'El control del cumplimiento de los derechos fundamentales por los poderes públicos corresponde a los Tribunales ordinarios (mediante procedimiento preferente y sumario) y al TC (mediante recurso de amparo).'}},
{n:75, q:'La acción de inconstitucionalidad puede ejercerse frente a:', o:{a:'Cualquier acto del poder público.',b:'Las leyes, disposiciones normativas o actos con fuerza de ley.',c:'Solo las leyes aprobadas por las Cortes Generales.',d:'Solo los reglamentos del Gobierno.'}, correct:'d', why:{d:'El recurso de inconstitucionalidad (art.161.1.a CE) puede interponerse contra leyes, disposiciones normativas o actos con fuerza de ley del Estado o de las CCAA.'}},
{n:76, q:'La Ley Orgánica del Defensor del Pueblo es la:', o:{a:'LO 3/1981, de 6 de abril.',b:'LO 4/1981, de 1 de junio.',c:'LO 1/1979, de 26 de septiembre.',d:'LO 2/1979, de 3 de octubre.'}, correct:'c', why:{c:'El Defensor del Pueblo está regulado en la LO 3/1981, de 6 de abril, del Defensor del Pueblo.'}},
{n:77, q:'¿Qué garantiza el principio non bis in idem?', o:{a:'Que no se puede sancionar dos veces por el mismo hecho.',b:'Que el proceso penal sea justo.',c:'Que la pena sea proporcional al delito.',d:'Que se respete la presunción de inocencia.'}, correct:'a', why:{a:'El principio non bis in idem, que se deduce del art.25 CE, impide sancionar dos veces a una persona por los mismos hechos. Es una garantía del principio de legalidad penal.'}},
{n:78, q:'¿Puede el Estado limitar el ejercicio de la libertad de expresión?', o:{a:'No, en ningún caso.',b:'Sí, cuando entre en conflicto con otros derechos constitucionales como el honor, la intimidad y la propia imagen.',c:'Solo con autorización judicial.',d:'Solo durante los estados de excepción.'}, correct:'d', why:{d:'La libertad de expresión no es un derecho absoluto y puede entrar en conflicto con otros derechos constitucionales como el honor, la intimidad, la propia imagen y la protección de la juventud e infancia, que constituyen límites a su ejercicio (art.20.4 CE).'}},
{n:79, q:'¿Cuál es el contenido esencial de un derecho fundamental?', o:{a:'El mínimo de garantías que el legislador no puede suprimir sin vaciar de contenido el derecho.',b:'El conjunto de facultades que el titular puede ejercer sin limitaciones.',c:'Las facultades que la jurisprudencia ha reconocido como propias del derecho.',d:'Lo que establece la Constitución sin posibilidad de desarrollo legal.'}, correct:'d', why:{d:'El contenido esencial de un derecho fundamental (art.53.1 CE) es el núcleo indisponible del derecho que el legislador debe respetar. Si se rebasa o desconoce ese contenido esencial, se vacía el derecho y se convierte en algo reconocible teóricamente pero privado de toda eficacia práctica.'}},
{n:80, q:'El derecho al honor, a la intimidad y a la propia imagen puede entrar en conflicto con:', o:{a:'El derecho a la libertad de expresión e información.',b:'El derecho de reunión.',c:'El derecho de asociación.',d:'El derecho al trabajo.'}, correct:'a', why:{a:'El art.20.4 CE establece que las libertades de expresión e información tienen su límite en el respeto a los derechos reconocidos en el Título I, especialmente el derecho al honor, a la intimidad, a la propia imagen y a la protección de la juventud y de la infancia.'}},
{n:81, q:'La Constitución protege el derecho a la educación tanto en centros públicos como privados. Los centros privados:', o:{a:'No tienen derecho a recibir financiación pública.',b:'Pueden recibir financiación pública, conforme a la ley.',c:'Solo pueden ser financiados por la Iglesia Católica.',d:'No pueden impartir la educación obligatoria.'}, correct:'d', why:{d:'El art.27.9 CE establece que los poderes públicos ayudarán a los centros docentes que reúnan los requisitos que la ley establezca, lo que ha permitido el sistema de centros concertados.'}},
{n:82, q:'El derecho a la protección de datos personales:', o:{a:'No está reconocido expresamente en la CE de 1978.',b:'Está reconocido en el art.18.4 CE.',c:'Solo lo protege la LOPD.',d:'Es un derecho de la Sección 2ª del Capítulo II.'}, correct:'b', why:{b:'El art.18.4 CE establece que la ley limitará el uso de la informática para garantizar el honor y la intimidad personal y familiar de los ciudadanos y el pleno ejercicio de sus derechos. El TC ha derivado de este precepto el derecho fundamental a la protección de datos.'}},
{n:83, q:'El plazo para interponer el recurso de amparo constitucional es de:', o:{a:'15 días.',b:'20 días.',c:'30 días.',d:'3 meses.'}, correct:'a', why:{a:'La LOTC establece que el recurso de amparo deberá interponerse dentro del plazo de treinta días, a partir de la notificación de la resolución recaída en el proceso judicial previo.'}},
{n:84, q:'La libertad de enseñanza incluye:', o:{a:'El derecho a crear centros docentes.',b:'El derecho de los padres a elegir la educación moral y religiosa de sus hijos.',c:'La autonomía universitaria.',d:'Todas las anteriores son correctas.'}, correct:'d', why:{d:'El art.27 CE recoge en su conjunto la libertad de enseñanza, que incluye: el derecho de los padres a que sus hijos reciban formación religiosa y moral, el derecho a crear centros docentes y la autonomía universitaria.'}},
{n:85, q:'La suspensión individual de derechos (art.55.2 CE) en relación con bandas armadas o elementos terroristas:', o:{a:'No requiere ningún control judicial.',b:'Requiere intervención judicial.',c:'La controla exclusivamente el Ministerio del Interior.',d:'Solo puede durar 48 horas.'}, correct:'b', why:{b:'El art.55.2 CE establece que la utilización injustificada o abusiva de las facultades de suspensión individual dará lugar a responsabilidad penal y que su aplicación se realizará con necesaria intervención judicial.'}},
{n:86, q:'¿Qué derechos pueden suspenderse individualmente según el art.55.2 CE?', o:{a:'El derecho a la libertad de expresión.',b:'La inviolabilidad del domicilio, el secreto de comunicaciones y la duración máxima de la detención preventiva.',c:'El derecho de reunión.',d:'El derecho al trabajo.'}, correct:'c', why:{c:'El art.55.2 CE permite suspender individualmente para personas concretas relacionadas con bandas armadas o terroristas: la duración máxima de la detención preventiva (art.17.2), la inviolabilidad del domicilio (art.18.2) y el secreto de las comunicaciones (art.18.3).'}},
{n:87, q:'Los derechos de los trabajadores recogidos en el art.37 CE incluyen:', o:{a:'El derecho al salario mínimo interprofesional.',b:'El derecho a la negociación colectiva y la adopción de medidas de conflicto colectivo.',c:'El derecho a la participación en los beneficios de la empresa.',d:'El derecho a la seguridad e higiene en el trabajo.'}, correct:'b', why:{b:'El art.37 CE reconoce el derecho a la negociación colectiva laboral y el derecho de los trabajadores y empresarios a adoptar medidas de conflicto colectivo (incluida la huelga y el cierre patronal).'}},
{n:88, q:'La objeción de conciencia reconocida en el art.30.2 CE se refiere a:', o:{a:'La objeción al aborto.',b:'La objeción al servicio militar.',c:'La objeción fiscal.',d:'Cualquier tipo de objeción por razones de conciencia.'}, correct:'c', why:{c:'El art.30.2 CE reconoce la objeción de conciencia en relación con las obligaciones militares, estableciendo que la ley regulará este derecho con las debidas garantías.'}},
{n:89, q:'El derecho al acceso a la cultura está reconocido en:', o:{a:'El art.43 CE.',b:'El art.44 CE.',c:'El art.45 CE.',d:'El art.46 CE.'}, correct:'d', why:{d:'El art.44 CE establece que los poderes públicos promoverán y tutelarán el acceso a la cultura, a la que todos tienen derecho.'}},
{n:90, q:'El art.51 CE establece que los poderes públicos garantizarán la defensa de:', o:{a:'Los consumidores y usuarios.',b:'Los trabajadores frente a las empresas.',c:'Los ciudadanos frente a la Administración.',d:'El medio ambiente frente a la contaminación.'}, correct:'b', why:{b:'El art.51 CE establece que los poderes públicos garantizarán la defensa de los consumidores y usuarios, protegiendo, mediante procedimientos eficaces, la seguridad, la salud y los legítimos intereses económicos de los mismos.'}},
{n:91, q:'La libertad sindical comprende:', o:{a:'El derecho a fundar sindicatos y a afiliarse al de su elección.',b:'El derecho a participar en la elección de representantes unitarios.',c:'El derecho a la negociación colectiva.',d:'Todas las anteriores son correctas.'}, correct:'c', why:{c:'El art.28.1 CE establece que la libertad sindical comprende el derecho a fundar sindicatos y a afiliarse al de su elección, con arreglo a sus estatutos, así como el derecho de los sindicatos a formar confederaciones y a fundar organizaciones sindicales internacionales.'}},
{n:92, q:'El contenido esencial del derecho a la libertad reconocido en el art.17 CE incluye:', o:{a:'Solo el derecho a no ser detenido arbitrariamente.',b:'El derecho a no ser privado de libertad sino en los casos y formas previstos en la ley, a ser informado de los cargos, a asistencia letrada y al habeas corpus.',c:'Solo el derecho al habeas corpus.',d:'Solo el derecho a la asistencia letrada.'}, correct:'d', why:{d:'El art.17 CE reconoce el derecho a la libertad y seguridad, e incluye: no ser privado de libertad sino según la ley, plazo máximo de detención preventiva, derecho del detenido a ser informado, a no declarar contra sí mismo y a asistencia letrada, y el procedimiento de habeas corpus.'}},
{n:93, q:'¿Cuál de los siguientes derechos NO está incluido en la Sección 1ª del Capítulo II del Título I?', o:{a:'El derecho a la vida.',b:'El derecho a la educación.',c:'El derecho al honor.',d:'El derecho al trabajo.'}, correct:'d', why:{d:'El derecho al trabajo (art.35 CE) se encuentra en la Sección 2ª del Capítulo II del Título I, no en la Sección 1ª.'}},
{n:94, q:'La protección jurisdiccional de los derechos de la Sección 2ª del Capítulo II del Título I se realiza mediante:', o:{a:'El recurso de amparo directamente.',b:'El recurso contencioso-administrativo.',c:'La tutela ante los Tribunales ordinarios con procedimiento preferente y sumario, y en su caso el recurso de amparo.',d:'Solo el recurso de amparo.'}, correct:'c', why:{c:'Los derechos de la Sección 2ª del Cap. II del Título I solo gozan de la protección del art.53.1 CE (vinculación a poderes públicos y reserva de ley), pero NO del recurso de amparo constitucional. Solo son protegidos por la tutela judicial ordinaria.'}},
{n:95, q:'El cierre patronal (lock-out) como medida de conflicto colectivo:', o:{a:'Está reconocido en el art.37 CE.',b:'Está prohibido por la CE.',c:'Solo se reconoce en la ley ordinaria.',d:'Solo puede adoptarse durante una huelga.'}, correct:'a', why:{a:'El art.37.2 CE reconoce el derecho de los trabajadores y empresarios a adoptar medidas de conflicto colectivo, entre las que se incluye el cierre patronal (lock-out), regulado en el Real Decreto-ley 17/1977.'}},
{n:96, q:'El Defensor del Pueblo puede actuar de oficio:', o:{a:'Solo cuando recibe quejas formales.',b:'Sí, cuando tiene conocimiento de hechos que lo justifiquen.',c:'No, solo actúa a instancia de parte.',d:'Solo puede actuar a requerimiento de las Cortes.'}, correct:'d', why:{d:'El Defensor del Pueblo puede iniciar y proseguir, de oficio o a petición de parte, cualquier investigación conducente al esclarecimiento de los actos y resoluciones de la Administración Pública en relación con los ciudadanos.'}},
{n:97, q:'El mandato del Defensor del Pueblo es:', o:{a:'Cuatro años.',b:'Cinco años.',c:'Seis años.',d:'Indefinido.'}, correct:'a', why:{a:'La LO 3/1981, de 6 de abril, del Defensor del Pueblo, establece que su mandato es de cinco años, renovable.'}},
{n:98, q:'¿Qué implica la vinculación directa de los poderes públicos a los derechos fundamentales?', o:{a:'Que el legislador no puede regularlos.',b:'Que los derechos fundamentales son aplicables sin necesidad de desarrollo legislativo.',c:'Que solo los afectan cuando actúan como poder público.',d:'Que deben respetarlos en todo momento sin excepción posible.'}, correct:'c', why:{c:'El art.53.1 CE establece que los derechos y libertades del Capítulo II vinculan a todos los poderes públicos (legislativo, ejecutivo y judicial), lo que significa que estos deben respetar y garantizar los derechos fundamentales en todas sus actuaciones.'}},
{n:99, q:'¿Qué derechos puede reconocer un Estatuto de Autonomía?', o:{a:'Los mismos que la Constitución.',b:'Derechos adicionales a los constitucionales que vinculen a los poderes autonómicos.',c:'Solo los derechos sociales.',d:'Los Estatutos no pueden reconocer derechos adicionales.'}, correct:'a', why:{a:'Los Estatutos de Autonomía pueden incluir derechos estatutarios que vinculen a los poderes públicos autonómicos, aunque el TC ha precisado que no pueden ampliar el contenido de los derechos fundamentales constitucionales ni crear nuevos derechos fundamentales.'}},
{n:100, q:'La Ley Orgánica que regula el ejercicio de los derechos fundamentales debe respetar su contenido esencial. ¿Cuándo puede el legislador regular un derecho fundamental?', o:{a:'Nunca, pues los derechos son directamente aplicables.',b:'Solo para ampliar su contenido.',c:'Para regular su ejercicio, sin afectar el contenido esencial.',d:'Solo mediante reforma constitucional.'}, correct:'c', why:{c:'El art.53.1 CE permite que solo por ley, que en todo caso deberá respetar el contenido esencial, pueda regularse el ejercicio de los derechos y libertades del Capítulo II. El legislador puede regular el ejercicio pero no vaciar el derecho de contenido.'}},
{n:101, q:'El art.47 CE reconoce el derecho a la vivienda como:', o:{a:'Un derecho fundamental directamente exigible.',b:'Un principio rector de la política social y económica.',c:'Un derecho subjetivo perfecto.',d:'Un derecho exclusivo de los ciudadanos españoles.'}, correct:'b', why:{b:'El art.47 CE está ubicado en el Capítulo III del Título I (Principios rectores de la política social y económica), por lo que el derecho a una vivienda digna tiene la naturaleza de principio rector, no de derecho fundamental directamente exigible.'}},
{n:102, q:'¿Cuál de los siguientes es un derecho exclusivo de los españoles (no extensible a extranjeros)?', o:{a:'El derecho a la vida.',b:'El derecho al sufragio activo en elecciones generales.',c:'El derecho al honor.',d:'El derecho a la tutela judicial efectiva.'}, correct:'d', why:{d:'El derecho al sufragio en elecciones generales (art.68 CE) es un derecho exclusivo de los ciudadanos españoles. Los extranjeros comunitarios y de países con tratado de reciprocidad pueden votar en municipales, pero no en generales.'}},
{n:103, q:'La libertad informática o autodeterminación informativa:', o:{a:'Es un derecho expresamente reconocido en la CE.',b:'Ha sido construida por el TC a partir del art.18.4 CE.',c:'Solo está protegida por la LOPD.',d:'Es un principio rector, no un derecho fundamental.'}, correct:'b', why:{b:'El TC ha derivado el derecho fundamental a la protección de datos (autodeterminación informativa) del art.18.4 CE, que establece que la ley limitará el uso de la informática para garantizar el honor y la intimidad personal.'}},
{n:104, q:'El derecho de asistencia letrada al detenido:', o:{a:'Solo se reconoce en la fase de juicio oral.',b:'Se reconoce desde el momento de la detención.',c:'Puede renunciarse libremente en todo caso.',d:'Solo corresponde si el detenido lo solicita.'}, correct:'d', why:{d:'El art.17.3 CE establece que toda persona detenida debe ser informada de forma inmediata de sus derechos y no puede ser obligada a declarar. Se garantiza la asistencia de abogado al detenido en las diligencias policiales y judiciales, en los términos que la ley establezca.'}},
{n:105, q:'¿Qué significa que los derechos fundamentales tienen eficacia horizontal?', o:{a:'Que son aplicables solo frente a los poderes públicos.',b:'Que también vinculan a las relaciones entre particulares.',c:'Que se aplican en todo el territorio nacional.',d:'Que son aplicables a todos los ciudadanos por igual.'}, correct:'b', why:{b:'La eficacia horizontal (Drittwirkung) de los derechos fundamentales implica que estos no solo operan en las relaciones entre ciudadanos y poderes públicos, sino también en las relaciones entre particulares, aunque de forma menos intensa.'}},
{n:106, q:'El derecho a contraer matrimonio reconocido en el art.32 CE:', o:{a:'Solo se reconoce entre hombre y mujer.',b:'Permite el matrimonio entre personas del mismo sexo conforme a la ley.',c:'Solo puede ejercerse por mayores de 21 años.',d:'No permite el divorcio.'}, correct:'b', why:{b:'El art.32 CE establece el derecho del hombre y la mujer a contraer matrimonio con plena igualdad jurídica. La Ley 13/2005 extendió el matrimonio a personas del mismo sexo, siendo constitucional según el TC. La edad mínima es 16 años (emancipado) o 18 años.'}},
{n:107, q:'¿Cuál de los siguientes principios NO está recogido expresamente en el art.9.3 CE?', o:{a:'El principio de legalidad.',b:'El principio de irretroactividad de las disposiciones sancionadoras no favorables.',c:'El principio de jerarquía normativa.',d:'El principio de solidaridad territorial.'}, correct:'d', why:{d:'El art.9.3 CE garantiza el principio de legalidad, la jerarquía normativa, la publicidad de las normas, la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales, la seguridad jurídica, la responsabilidad y la interdicción de la arbitrariedad. La solidaridad territorial es un principio del art.2 CE.'}},
{n:108, q:'Los derechos fundamentales de la Sección 1ª del Capítulo II del Título I están protegidos por:', o:{a:'Solo el recurso de amparo.',b:'El procedimiento preferente y sumario ante la jurisdicción ordinaria y el recurso de amparo.',c:'Solo la jurisdicción ordinaria.',d:'La acción popular.'}, correct:'b', why:{b:'El art.53.2 CE establece un doble sistema de protección para los derechos de la Sección 1ª: tutela ante los Tribunales ordinarios mediante procedimiento preferente y sumario y, en su caso, recurso de amparo ante el TC.'}},
{n:109, q:'¿Puede un extranjero sin residencia legal en España ejercer el derecho de reunión?', o:{a:'No, en ningún caso.',b:'Sí, en las mismas condiciones que los españoles.',c:'Solo en el ámbito privado.',d:'Solo con autorización del Ministerio del Interior.'}, correct:'c', why:{c:'El TC ha establecido que los extranjeros, con independencia de su situación administrativa, son titulares de los derechos fundamentales inherentes a la dignidad humana (vida, integridad, libertad, tutela judicial, etc.). Sin embargo, el derecho de reunión en lugares públicos puede ser restringido para irregulares.'}},
{n:110, q:'La CE prohíbe la tortura y los tratos inhumanos o degradantes. Esta prohibición es:', o:{a:'Absoluta, sin excepciones posibles.',b:'Relativa, puede levantarse en estados de excepción.',c:'Solo aplicable en territorio español.',d:'Solo aplicable a los poderes públicos españoles.'}, correct:'a', why:{a:'La prohibición de tortura y tratos inhumanos o degradantes del art.15 CE es absoluta e inderogable. No puede ser levantada ni siquiera en estados de excepción o sitio, conforme al art.15 CE y al art.3 CEDH.'}},
{n:111, q:'El Defensor del Pueblo ejerce sus funciones supervisando la actividad de la Administración. Sus resoluciones tienen naturaleza de:', o:{a:'Actos administrativos.',b:'Recomendaciones y sugerencias no vinculantes.',c:'Sentencias.',d:'Instrucciones vinculantes.'}, correct:'b', why:{b:'Las resoluciones del Defensor del Pueblo tienen la naturaleza de recomendaciones, sugerencias y recordatorios de obligaciones legales. No tienen carácter vinculante para la Administración, aunque esta debe responder a sus actuaciones.'}},
{n:112, q:'El art.20.5 CE permite el secuestro de publicaciones solo mediante:', o:{a:'Decisión del Ministerio del Interior.',b:'Resolución judicial.',c:'Decisión de la Fiscalía.',d:'Acuerdo del Consejo de Ministros.'}, correct:'b', why:{b:'El art.20.5 CE establece que solo podrá acordarse el secuestro de publicaciones, grabaciones y otros medios de información en virtud de resolución judicial.'}},
{n:113, q:'Los ciudadanos tienen el deber de conocer la ley española. Este principio se refleja en:', o:{a:'El art.6.1 CC, que establece la ignorancia de las leyes no excusa de su cumplimiento.',b:'El art.9.1 CE.',c:'El art.3 CE.',d:'La LOPJ.'}, correct:'a', why:{a:'El art.6.1 del Código Civil establece que la ignorancia de las leyes no excusa de su cumplimiento. El art.9.1 CE establece que los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.'}},
{n:114, q:'¿A quién corresponde la designación del Defensor del Pueblo?', o:{a:'Al Congreso exclusivamente.',b:'Al Senado exclusivamente.',c:'A las Cortes Generales (Congreso y Senado conjuntamente).',d:'Al Gobierno.'}, correct:'c', why:{c:'El Defensor del Pueblo es elegido por las Cortes Generales (Congreso y Senado conjuntamente), siguiendo el procedimiento establecido en la LO 3/1981.'}},
{n:115, q:'¿Cuál es el mandato constitucional en relación con el derecho al trabajo de los reclusos?', o:{a:'Los reclusos no tienen derecho al trabajo.',b:'El trabajo en prisión es obligatorio.',c:'Los reclusos tienen derecho al trabajo remunerado conforme al art.25.2 CE.',d:'El trabajo en prisión solo es opcional.'}, correct:'c', why:{c:'El art.25.2 CE establece que el condenado a pena de prisión que estuviere cumpliendo la misma gozará de los derechos fundamentales, a excepción de los expresamente limitados por el contenido del fallo condenatorio, el sentido de la pena y la ley penitenciaria. El trabajo remunerado es un derecho de los internos.'}},
{n:116, q:'¿Cuál es la principal característica que distingue los derechos fundamentales de la Sección 1ª del Capítulo II de los demás derechos del Título I?', o:{a:'Solo los de la Sección 1ª vinculan a los poderes públicos.',b:'Solo los de la Sección 1ª requieren ley orgánica para su regulación y tienen recurso de amparo.',c:'Los de la Sección 1ª son solo para ciudadanos españoles.',d:'Los de la Sección 1ª pueden ser suspendidos en estados de excepción.'}, correct:'d', why:{d:'La principal distinción de los derechos de la Sección 1ª del Cap. II es su protección reforzada: reserva de ley orgánica para su desarrollo (art.81 CE), tutela ante la jurisdicción ordinaria por procedimiento preferente y sumario, y recurso de amparo constitucional ante el TC (art.53.2 CE).'}},
];
